/**
 * The files the fake PC's agents shared (mock.ts), one of each kind the
 * phone shows and one it does not. Drawn, written or generated here rather
 * than shipped, but for a video of two seconds, which no code draws: 2.5 kB.
 */

/** Two seconds of moving gradient, H.264 baseline, 160×90: what a video share plays in the fake PC. */
const CLIP_MP4 = "";

const RETRY_TS = `/**
 * Retries a request that failed for a reason worth retrying: the network,
 * a 429 or a 5xx. Each wait is longer than the last, with jitter.
 */
export interface RetryOptions {
  attempts?: number;
  baseMs?: number;
  maxMs?: number;
}

const RETRYABLE = new Set([408, 425, 429, 500, 502, 503, 504]);

export async function withRetry<T>(
  run: () => Promise<Response>,
  parse: (response: Response) => Promise<T>,
  { attempts = 4, baseMs = 250, maxMs = 4_000 }: RetryOptions = {},
): Promise<T> {
  let last: unknown;
  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      const response = await run();
      if (response.ok) return await parse(response);
      if (!RETRYABLE.has(response.status)) throw new Error(\`HTTP \${response.status}\`);
      last = new Error(\`HTTP \${response.status}\`);
    } catch (error) {
      last = error;
    }
    // Full jitter: anywhere between 0 and the capped exponential delay.
    const delay = Math.random() * Math.min(maxMs, baseMs * 2 ** attempt);
    await new Promise((resolve) => setTimeout(resolve, delay));
  }
  throw last;
}
`;

