function invoicesCsv(): string {
  const customers = ["Atelier Morel", "Brasserie du Port", "Cycles Lenoir", "Duval & Fils", "Éditions Kléber", "Fromagerie Alpine"];
  const rows = ["invoice,customer,issued,amount_eur,vat_eur,status"];
  for (let n = 1; n <= 48; n++) {
    const amount = 180 + ((n * 7919) % 4200);
    rows.push(
      [`F-2026-10-${String(n).padStart(3, "0")}`, customers[n % customers.length], `2026-10-${String(1 + (n % 28)).padStart(2, "0")}`, amount.toFixed(2), (amount * 0.2).toFixed(2), n % 9 === 0 ? "overdue" : n % 4 === 0 ? "sent" : "paid"].join(","),
    );
  }
  return `${rows.join("\n")}\n`;
}

/** A build log of a few MB: what the phone shows the head of. */
function buildLog(): string {
  const lines: string[] = [];
  const steps = 26_000;
  for (let n = 0; n < steps; n++) {
    const second = Math.floor(n / 40);
    const stamp = `2026-10-29T06:${String(12 + Math.floor(second / 60)).padStart(2, "0")}:${String(second % 60).padStart(2, "0")}.${String((n * 37) % 1000).padStart(3, "0")}Z`;
    const level = n % 997 === 0 ? "WARN " : "INFO ";
    lines.push(`${stamp} ${level} cargo  Compiling crate-${n % 311} v0.${n % 9}.${n % 13} (step ${n + 1}/${steps})`);
  }
  lines.push("2026-10-29T06:23:02.114Z ERROR cargo  error[E0308]: mismatched types in src/remote/files.rs:212");
  return `${lines.join("\n")}\n`;
}

function scoreRing(label: string, score: number): string {
  const color = score >= 90 ? "#0c7d3a" : score >= 50 ? "#c33300" : "#cc0f35";
  const length = 2 * Math.PI * 26;
  return `<div class="score"><svg class="ring" viewBox="0 0 64 64"><circle cx="32" cy="32" r="26" fill="none" stroke="#8883" stroke-width="6"/><circle cx="32" cy="32" r="26" fill="none" stroke="${color}" stroke-width="6" stroke-linecap="round" stroke-dasharray="${((length * score) / 100).toFixed(1)} ${length.toFixed(1)}" transform="rotate(-90 32 32)"/><text x="32" y="38" text-anchor="middle" font-size="17" font-family="system-ui,sans-serif" fill="${color}">${score}</text></svg><div class="label">${label}</div></div>`;
}

