/** One page of A5 with a title and two lines, its cross-reference table counted. */
function invoicePdf(): string {
  const text = [
    "BT /F1 22 Tf 40 520 Td (Invoice F-2026-10-042) Tj ET",
    "BT /F1 12 Tf 40 492 Td (billing-api, October 2026) Tj ET",
    "BT /F1 12 Tf 40 450 Td (Hosting and support .......... 1 240.00 EUR) Tj ET",
    "BT /F1 12 Tf 40 430 Td (VAT 20 % ....................... 248.00 EUR) Tj ET",
  ].join("\n");
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 420 595] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>",
    `<< /Length ${text.length} >>\nstream\n${text}\nendstream`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ];
  let pdf = "%PDF-1.4\n";
  const offsets = objects.map((object, index) => {
    const offset = pdf.length;
    pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
    return offset;
  });
  const xref = pdf.length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.map((offset) => `${String(offset).padStart(10, "0")} 00000 n \n`).join("")}`;
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return pdf;
}

/** A chime of two notes, 8 kHz, 8-bit mono WAV. */
function chimeWav(): Uint8Array {
  const rate = 8000;
  const samples = Math.round(rate * 1.6);
  const bytes = new Uint8Array(44 + samples);
  const view = new DataView(bytes.buffer);
  const ascii = (at: number, text: string) => [...text].forEach((c, i) => view.setUint8(at + i, c.charCodeAt(0)));
  ascii(0, "RIFF");
  view.setUint32(4, 36 + samples, true);
  ascii(8, "WAVEfmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, rate, true);
  view.setUint32(28, rate, true);
  view.setUint16(32, 1, true);
  view.setUint16(34, 8, true);
  ascii(36, "data");
  view.setUint32(40, samples, true);
  for (let n = 0; n < samples; n++) {
    const time = n / rate;
    const note = time < 0.6 ? 660 : 880;
    const since = time < 0.6 ? time : time - 0.6;
    const level = Math.sin(2 * Math.PI * note * time) * Math.exp(-3.5 * since) * 0.45;
    bytes[44 + n] = Math.round(128 + 127 * level);
  }
  return bytes;
}

const fromBase64 = (base64: string) => Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
const utf8 = (text: string) => new TextEncoder().encode(text);

/** Each file's bytes, made the first time they are asked for. */
const MAKERS: Record<string, () => Uint8Array> = {
  "s-clip": () => fromBase64(CLIP_MP4),
  "s-retry": () => utf8(RETRY_TS),
  "s-notes": () => utf8(RELEASE_NOTES),
  "s-lighthouse": () => utf8(lighthousePage()),
  "s-log": () => utf8(buildLog()),
  "s-voice": chimeWav,
  "s-invoice": () => utf8(invoicePdf()),
  "s-csv": () => utf8(invoicesCsv()),
  "s-bundle": () => utf8("PK\u0003\u0004 a fake archive"),
};

const made = new Map<string, Uint8Array>();

/** A shared file's bytes, if the fake PC has them (its pictures are drawn by mock.ts). */
export function fakeFile(id: string): Uint8Array | undefined {
  const make = MAKERS[id];
  if (!make) return undefined;
  let bytes = made.get(id);
  if (!bytes) made.set(id, (bytes = make()));
  return bytes;
}

const urls = new Map<string, string>();

/**
 * Where the phone reads a fake file from: a blob it can play or open like
 * the PC's own file, and a page as a data: address, which is no origin's
 * wherever it opens.
 */
export function fakeFileUrl(id: string, mime: string): string {
  const bytes = fakeFile(id) ?? new Uint8Array();
  if (mime.startsWith("text/html")) return `data:${mime},${encodeURIComponent(new TextDecoder().decode(bytes))}`;
  let url = urls.get(id);
  if (!url) {
    url =
      typeof URL.createObjectURL === "function"
        ? URL.createObjectURL(new Blob([bytes as BlobPart], { type: mime }))
        : `data:${mime};base64,${btoa(String.fromCharCode(...bytes.subarray(0, 4096)))}`;
    urls.set(id, url);
  }
  return url;
}

/** The fake PC's answer to a file's GET: whole, or the one byte range asked for, as the PC serves it. */
export function fileResponse(bytes: Uint8Array, mime: string, range: string | null): Response {
  const asked = /^bytes=(\d*)-(\d*)$/.exec(range?.trim() ?? "");
  const headers = { "Content-Type": mime, "Accept-Ranges": "bytes" };
  if (!asked) return new Response(bytes as BodyInit, { status: 200, headers });
  const [, first, last] = asked;
  const len = bytes.length;
  const start = first === "" ? Math.max(0, len - Number(last)) : Number(first);
  const end = first === "" || last === "" ? len - 1 : Math.min(Number(last), len - 1);
  if (start >= len || end < start) return new Response(null, { status: 416, headers: { "Content-Range": `bytes */${len}` } });
  return new Response(bytes.slice(start, end + 1) as BodyInit, {
    status: 206,
    headers: { ...headers, "Content-Range": `bytes ${start}-${end}/${len}` },
  });
}
